using BenchmarkDotNet.Attributes;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using OptimizingEfCoreQueries.Shared;
using OptimizingEfCoreQueries.Scenarios;

namespace OptimizingEfCoreQueries.Benchmarks;

// Baseline finds articles by prefix with a leading-wildcard Contains that scans
// every row's full text; Optimized calls the agent-owned
// LeadingWildcardSolution.Run. The prefix only ever appears at the start of a
// reference, so an anchored and a substring match return the SAME ids — only the
// per-row scan cost differs. Do not edit this file — edit
// Scenarios/LeadingWildcard.cs.
[Config(typeof(SharedBenchmarkConfig))]
public class LeadingWildcardBenchmark
{
    // Matches references article-000100-.. through article-000199-.., and because
    // the six-digit number appears only at the start, Contains and StartsWith
    // select exactly the same rows.
    private const string Prefix = "article-0001";
    private SqliteConnection _connection = null!;

    [GlobalSetup]
    public void Setup()
    {
        _connection = AppDbContext.OpenSharedConnection();
        using var db = AppDbContext.Create(_connection);
        db.Database.EnsureCreated();
        SeedData.SeedArticles(db, articles: 60000, bodyChars: 300);

        EquivalenceGuard.SameResults(Baseline(), Optimized(), id => id.ToString());
    }

    [GlobalCleanup]
    public void Cleanup() => _connection.Dispose();

    [Benchmark(Baseline = true)]
    public List<int> Baseline()
    {
        using var db = AppDbContext.Create(_connection);
        return db.Articles
            .Where(a => a.Reference.Contains(Prefix))
            .OrderBy(a => a.Id)
            .Select(a => a.Id)
            .ToList();
    }

    [Benchmark]
    public List<int> Optimized()
    {
        using var db = AppDbContext.Create(_connection);
        return LeadingWildcardSolution.Run(db, Prefix);
    }
}
